import test from 'node:test';
import assert from 'node:assert/strict';
import {createReadinessBoundary} from '../readiness/readiness-boundary.mjs';
import {environment,SPEC,RECEIPT,fence,delay} from './synthetic-fixture.mjs';
const spec={transaction:SPEC.transaction,nonce:SPEC.nonce,image:SPEC.image,receiverSourceSha256:SPEC.sourcePins.receiver};
const warm=s=>({...s,inputBytes:0,verifiedBeforeStop:true});
const ready=e=>({transaction:e.transaction,nonce:e.nonce,expectedSha256:e.expectedSha256,expectedManifestSha256:e.expectedManifestSha256,...e.sourceWitness,inputBytes:0});
test('128 cancelled unresolved warm attempts invoke port once',async()=>{let calls=0;const b=createReadinessBoundary({prepareBeforeStop:()=>{calls++;return new Promise(()=>{});},bindAfterAuthentication:ready});for(let i=0;i<128;i++){const c=new AbortController();const p=b.warmBeforeServingStop(spec,{signal:c.signal});c.abort();await assert.rejects(p,{code:i?'readiness_capacity_exhausted':'readiness_cancelled'});}assert.equal(calls,1);});
test('warm getter, proxy and symbol records cannot execute payload or mint lease',async()=>{for(const kind of ['getter','proxy','symbol']){let reads=0;const b=createReadinessBoundary({prepareBeforeStop:s=>{const v=warm(s);if(kind==='getter')Object.defineProperty(v,'verifiedBeforeStop',{enumerable:true,get(){reads++;return true;}});if(kind==='symbol')v[Symbol()]=true;return kind==='proxy'?new Proxy(v,{ownKeys(){reads++;return Reflect.ownKeys(v);},get(t,k){if(k==='then')return undefined;reads++;return t[k];}}):v;},bindAfterAuthentication:ready});await assert.rejects(b.warmBeforeServingStop(spec));assert.equal(reads,0);}});
test('ready accessor cancelled or not cannot pass final body fence',async()=>{let reads=0;let b,lease;b=createReadinessBoundary({prepareBeforeStop:warm,bindAfterAuthentication:e=>{const v=ready(e);Object.defineProperty(v,'nonce',{enumerable:true,get(){reads++;b.cancel(lease);return e.nonce;}});return v;}});lease=await b.warmBeforeServingStop(spec);b.noteServingStopped(lease);b.captureLaterBackup(lease,RECEIPT);await assert.rejects(b.beforeBody(lease)({check(){},authenticated:RECEIPT}));assert.equal(reads,0);});
test('native abort in receiver body-start telemetry must not dispatch receiver',async()=>{let env;env=environment({emit:r=>{if(r.phase==='body_receiver_start')env.abort.abort();}});try{await env.client.warmBeforeServingStop();await env.client.bindInsideAuthenticatedHook(RECEIPT,fence(RECEIPT)).catch(()=>{});await env.rawRun.catch(()=>{});assert.equal(env.counts.receiveCalls,0,'receiver dispatch occurs after native cancellation');}finally{await env.close();}});

test('synchronous nested warm cannot duplicate port dispatch',async()=>{let b,nested,calls=0;b=createReadinessBoundary({prepareBeforeStop:s=>{calls++;nested=b.warmBeforeServingStop(spec).catch(e=>e.code);return warm(s);},bindAfterAuthentication:ready});await b.warmBeforeServingStop(spec);assert.equal(await nested,'readiness_capacity_exhausted');assert.equal(calls,1);});
test('cancel from bound telemetry denies final body admission',async()=>{let b,lease;b=createReadinessBoundary({prepareBeforeStop:warm,bindAfterAuthentication:ready,emit:r=>{if(r.phase==='bound_read0_inside_sender_budget')b.cancel(lease);}});lease=await b.warmBeforeServingStop(spec);b.noteServingStopped(lease);b.captureLaterBackup(lease,RECEIPT);await assert.rejects(b.beforeBody(lease)({check(){},authenticated:RECEIPT}),{code:'readiness_cancelled'});});
test('cancel inside final check cannot commit body admission',async()=>{let b,lease,checks=0;b=createReadinessBoundary({prepareBeforeStop:warm,bindAfterAuthentication:ready});lease=await b.warmBeforeServingStop(spec);b.noteServingStopped(lease);b.captureLaterBackup(lease,RECEIPT);await assert.rejects(b.beforeBody(lease)({check(){if(++checks===2)b.cancel(lease);},authenticated:RECEIPT}),{code:'readiness_cancelled'});});
